function beginnerGuide(track,id,title,minutes,intro,concept,example,explain,steps,quiz,extra={}){
 guide({track,id,title,minutes,intro,concept,example,explain,steps,
  checks:['我亲手完成了本课的小操作','我能不用照抄，用自己的话说出本课结论'],
  quiz:{q:quiz.q,options:quiz.options,answer:quiz.answer,explanation:quiz.explanation},
  hint:extra.hint||'先只做第一小步。看清屏幕有没有变化，再继续下一步。',
  reflection:extra.reflection||'如果把这一步讲给第一次用电脑的人，你会怎么说？',
  vocab:extra.vocab||[],rescue:extra.rescue||[],mistakes:extra.mistakes||[],mini:extra.mini,
  source:extra.source
 });
}
const q=(question,options,answer,explanation)=>({q:question,options,answer,explanation});

beginnerGuide('computer-zero','pc-01','电脑、程序和网页不是一回事',15,
 '你现在看到的是一个网页。先分清几个常被混在一起的词，以后遇到问题才知道应该检查哪里。',
 '<strong>电脑</strong>是整台设备；<strong>操作系统</strong>负责管理屏幕、键盘和文件；<strong>程序</strong>是在电脑上运行的工具；<strong>浏览器</strong>是一种程序；<strong>网页</strong>是浏览器打开的内容。',
 '电脑 → Windows → 浏览器 → 循码网页',
 '它们像一栋楼：电脑是楼，Windows 是物业，浏览器是一个房间，网页是房间里摊开的书。网页卡住时，电脑本身不一定坏了。',
 ['看看屏幕顶部：找到浏览器标签页和地址栏。','说出你现在用的是哪台设备、哪个程序、哪个网页。','点击本课小游戏，把四个名称按从大到小的包含关系排列。'],
 q('你正在循码里学习。循码最准确属于什么？',['电脑','操作系统','浏览器里的网页'],2,'循码是浏览器打开的网页。'),
 {vocab:[['程序','帮你完成某类工作的软件'],['浏览器','用来打开网页的程序'],['网页','浏览器中显示的一页内容']],rescue:['找不到地址栏：看窗口最上方、显示 http 或网站名字的长条。','不知道浏览器名字：这不影响学习，先知道它负责打开网页即可。'],mini:{type:'order',prompt:'按“外面 → 里面”的顺序点击',items:['循码网页','电脑','Windows','浏览器'],answer:['电脑','Windows','浏览器','循码网页']}});

beginnerGuide('computer-zero','pc-02','鼠标的四个动作',15,
 '鼠标不是只有“点”。单击、双击、右击和拖动会告诉电脑四种不同的意图。',
 '<strong>单击</strong>通常是选择或按按钮；<strong>双击</strong>常用于打开桌面文件；<strong>右击</strong>打开更多操作；<strong>拖动</strong>是按住不放再移动。网页按钮通常只需单击一次。',
 '单击 = 点一下马上松开\n拖动 = 按住 → 移动 → 松开',
 '如果网页按钮没有反应，不要连续猛点。先等一秒，看按钮是否变灰、页面是否出现提示。重复点击可能重复提交。',
 ['在小游戏里依次单击出现的三个目标。','滚动页面：鼠标滚轮向下是看后面的内容，向上是回到前面。','说出打开桌面文件和按网页按钮通常分别用哪种点击。'],
 q('网页上的“下一步”按钮通常怎样操作？',['单击一次','双击很多次','一直按住不放'],0,'网页按钮通常单击一次。'),
 {vocab:[['单击','按下并马上松开一次'],['拖动','按住、移动、再松开'],['滚动','把页面前后内容移入视野']],rescue:['触控板单击：轻点一次，或按下左下区域。','点错不会损坏课程，小游戏会让你重试。'],mini:{type:'targets',prompt:'按数字顺序点击目标',items:['1','2','3']}});

beginnerGuide('computer-zero','pc-03','键盘、光标和输入框',18,
 '打字前必须先告诉电脑“文字要放在哪里”。输入框里闪动的竖线叫光标。',
 '先单击输入框，看到闪动光标后再打字。<strong>Backspace</strong> 删除光标左边一个字符；<strong>Enter</strong> 常表示换行或确认；<strong>Shift</strong> 配合字母可输入大写。代码里的符号要用英文输入法。',
 '先点击这里 → 看到 | → 再输入文字',
 '中文输入法负责把拼音变成汉字；代码符号通常使用英文半角。全角的（ ）和半角的 ( ) 看起来相近，但电脑把它们当作不同字符。',
 ['点击小游戏输入框，完整输入指定短句。','故意多输入一个字，用 Backspace 删除。','切换中英文输入法，分别输入：你好 和 print()。'],
 q('打字出现在错误的位置，最可能漏了哪一步？',['先点击正确的输入框','先关机','多按几次空格'],0,'先让正确输入框获得焦点。'),
 {vocab:[['光标','告诉你下一字符会出现在哪里的竖线'],['输入框','允许输入文字的区域'],['半角符号','编程常用的英文宽度符号']],rescue:['没有文字：先单击输入框，再输入。','符号不对：切到英文输入法后重新输入。'],mini:{type:'typing',prompt:'准确输入：hello()',target:'hello()'}});

beginnerGuide('computer-zero','pc-04','窗口、标签页和前进后退',15,
 '一个屏幕可以同时打开多个程序；浏览器里又可以打开多个标签页。迷路时不要立刻关闭所有东西。',
 '窗口右上角通常有最小化、最大化和关闭。浏览器标签页像书签夹着的不同页面；地址栏显示当前位置；后退按钮返回刚才的页面。',
 '窗口\n ├─ 标签页：循码\n └─ 标签页：搜索资料',
 '关闭标签页只关当前网页；关闭整个浏览器窗口会一起关掉这个窗口里的标签。课程进度保存在浏览器里，但还应定期备份。',
 ['找到当前标签页的标题。','新开一个空白标签页，再回到循码标签页。','在不关闭页面的情况下，指出后退按钮和地址栏。'],
 q('想回到刚才浏览的页面，优先尝试什么？',['浏览器后退按钮','拔掉电源','删除文件'],0,'后退按钮用于返回上一页。'),
 {vocab:[['窗口','一个程序在屏幕上的工作区域'],['标签页','浏览器中并排打开的多个网页'],['地址栏','显示或输入网页地址的位置']],mini:{type:'choice',prompt:'哪个操作只会关掉当前网页？',options:['关闭当前标签页','关闭整个浏览器','关机'],answer:0}});

beginnerGuide('computer-zero','pc-05','文件、文件夹、名字和后缀',20,
 '代码最终会保存在文件里。先理解文件和文件夹，才不会出现“明明保存了却找不到”。',
 '<strong>文件</strong>是一份内容；<strong>文件夹</strong>用来分类装文件；<strong>路径</strong>是从某个位置走到文件的路线；<strong>后缀</strong>是文件名最后的 .txt、.py 等，帮助判断类型。',
 '学习资料/\n ├─ 笔记.txt\n └─ hello.py',
 'hello.py 的名字是 hello.py，.py 表示 Python 文件。不要只凭图标判断类型。Windows 有时会隐藏已知后缀，学习编程时建议显示文件扩展名。',
 ['在自己的文档目录新建“codepath-labs”文件夹。','在里面新建“第一课笔记.txt”，写一句话并保存。','关闭后重新找到并打开它，确认不是只记住“最近使用”。'],
 q('路径最像下面哪一样东西？',['到达文件的一串地址','文件里面的第一句话','鼠标颜色'],0,'路径描述文件在哪里。'),
 {vocab:[['文件','保存的一份内容'],['文件夹','组织多个文件的容器'],['路径','文件所在位置的路线'],['后缀','文件名末尾表示类型的部分']],rescue:['找不到文件：回想保存时选择的文件夹，不要反复另存新副本。','分不清文件与文件夹：文件能打开看内容，文件夹打开后还会列出其他项目。'],mini:{type:'choice',prompt:'哪个是 Python 文件？',options:['练习','练习.py','练习文件夹'],answer:1}});

beginnerGuide('computer-zero','pc-06','下载、压缩包和解压',18,
 '从网上下载的项目常是 ZIP 压缩包。直接在压缩包预览里运行，容易出现路径和权限问题。',
 '<strong>下载</strong>把网络内容保存到本机；<strong>ZIP</strong>像把许多文件装进一个封口袋；<strong>解压</strong>是把内容取到普通文件夹。解压后再进入真正的项目目录。',
 'codepath.zip → 解压到 → codepath/ → README.md、dist/、tests/',
 '同名压缩包和解压后的文件夹可能同时存在。先看图标和后缀，再确认自己打开的是文件夹。来源不明的可执行文件不要随便运行。',
 ['找到浏览器的下载列表。','在练习目录中创建一个小文件夹并压缩，再解压到新位置。','比较 ZIP 文件和解压文件夹的图标、大小和里面内容。'],
 q('下载项目 ZIP 后，正常下一步是什么？',['先解压到普通文件夹','一直在压缩包预览里改','把后缀删除'],0,'项目应先解压再使用。'),
 {vocab:[['下载','从网络保存到本机'],['压缩包','把多个文件压缩成一个文件'],['解压','还原为普通文件和文件夹']],mini:{type:'order',prompt:'按正确顺序点击',items:['打开项目文件夹','下载 ZIP','解压'],answer:['下载 ZIP','解压','打开项目文件夹']}});

beginnerGuide('computer-zero','pc-07','什么是终端：用文字命令电脑',20,
 '终端不是黑客工具，也不是看到黑底窗口就危险。它只是另一种操作电脑的方式：输入文字命令，读取文字结果。',
 '一条命令通常包含“做什么”和“对谁做”。提示符表示终端正在等你输入。按 Enter 才执行。命令执行前先确认当前位置和目标，不复制看不懂的删除命令。',
 '命令：pwd\n作用：显示当前所在目录\n它不会删除任何东西',
 '网页按钮把操作藏在图形后面；终端把操作写成文字。文字方式更容易记录、重复和自动化，也更需要精确。',
 ['本课只观察，不安装软件：找到一张终端示意或打开已有终端。','识别提示符、输入区域和输出区域。','把“显示当前目录”和“删除整个目录”按风险高低分类。'],
 q('终端里输入命令后，通常按什么才执行？',['Enter','Shift','Caps Lock'],0,'Enter 通常提交命令。'),
 {vocab:[['终端','用文字命令操作电脑的界面'],['命令','告诉电脑要做的具体动作'],['输出','电脑执行后显示的结果']],rescue:['害怕输错：先只使用课程明确给出的只读命令。','不要运行来源不明、你无法解释的命令。'],mini:{type:'choice',prompt:'哪条描述风险最低？',options:['显示当前目录','永久删除所有文件','关闭安全软件'],answer:0}});

beginnerGuide('computer-zero','pc-08','看懂报错并学会求助',22,
 '报错不是“我不适合编程”，它是电脑告诉你在哪一步无法继续。高手和新手都会遇到错误，区别在于是否保留证据。',
 '一次有效求助至少有：你想做什么、实际发生什么、完整错误文字、操作步骤、环境。不要只说“不能用”。复制错误时保留第一行、最后一行和文件/行号；发送前去掉密码、密钥和隐私。',
 '目标：运行 hello.py\n命令：python hello.py\n实际：第 3 行 SyntaxError\n我尝试过：检查英文括号',
 '截图能保留界面，但文字更方便搜索。最好的记录通常同时有可复制错误文字和必要截图。',
 ['在小游戏中从三条信息里选出有效报错记录。','练习选中、复制和粘贴一段无隐私文字。','用“目标—步骤—结果—尝试”四句模板描述一个小问题。'],
 q('哪种求助最容易得到准确帮助？',['坏了，怎么办','运行第 3 步后显示完整错误……这是命令和环境','把账号密码一起发出'],1,'清楚的目标、步骤和完整错误最有用。'),
 {vocab:[['报错','电脑无法继续时给出的信息'],['复现','按同样步骤再次出现同一问题'],['环境','操作系统、版本等运行条件']],mini:{type:'choice',prompt:'选择最有效且安全的求助信息',options:['不能用','目标、步骤、完整错误、环境（已隐去密钥）','账号密码和一句“帮我”'],answer:1}});

beginnerGuide('thinking-zero','think-01','指令必须具体：电脑不会猜',18,
 '人能理解“把房间整理一下”，电脑不知道“整理”具体包含什么。编程先把模糊目标拆成可执行动作。',
 '好指令要说明动作、对象和顺序。例如“拿起桌上的红色杯子，放到水槽左边”。遗漏对象或位置，会产生多种理解。',
 '模糊：处理名单\n具体：读取名单 → 去掉空白行 → 按姓名排序 → 保存新文件',
 '拆步骤不是为了写得长，而是让每一步都能检查。遇到复杂项目时，继续把大步骤拆成更小步骤。',
 ['把“发一封邮件”拆成至少四个步骤。','检查每一步是否只有一个明确动作。','在排序小游戏中按合理顺序选择动作。'],
 q('哪条指令更适合电脑执行？',['把它弄好','读取数字，乘 2，然后显示结果','你看着办'],1,'动作、数据和顺序都明确。'),
 {vocab:[['指令','要求电脑执行的一个明确动作'],['顺序','动作发生的先后'],['检查点','可以确认这一步是否成功的结果']],mini:{type:'order',prompt:'做一杯水的合理顺序',items:['喝水','接水','拿杯子'],answer:['拿杯子','接水','喝水']}});

beginnerGuide('thinking-zero','think-02','输入、处理和输出',18,
 '多数程序都可以先用三个盒子理解：它拿到什么、做了什么、给出什么。',
 '<strong>输入</strong>是程序收到的数据；<strong>处理</strong>是规则或计算；<strong>输出</strong>是最后显示、保存或发出的结果。程序也可能有多个输入和输出。',
 '输入：单价 8、数量 2\n处理：8 × 2\n输出：16',
 '按钮点击也是输入；数据库查询是处理的一部分；屏幕文字是一种输出。先画出三盒模型，有助于读陌生代码。',
 ['给“天气应用”分别写一个输入、处理和输出。','给“计算年龄”写出三盒模型。','完成小游戏，把信息放到正确盒子。'],
 q('用户在搜索框输入关键词，属于什么？',['输入','处理','输出'],0,'用户交给程序的数据是输入。'),
 {vocab:[['输入','交给程序的数据或动作'],['处理','程序按照规则做的事'],['输出','程序给出的结果']],mini:{type:'choice',prompt:'计算器屏幕显示 12，属于哪一盒？',options:['输入','处理','输出'],answer:2}});

beginnerGuide('thinking-zero','think-03','数据有不同类型',20,
 '电脑需要区分文字、数字和真假。看起来一样的数据，类型不同，允许的操作也不同。',
 '数字可以正常加减；文字可以拼接；真假只有“是/否”两种状态。文字 "12" 和数字 12 看起来接近，但前者是两个字符。',
 '数字：12 + 3 = 15\n文字："12" + "3" = "123"\n真假：已登录 = 是',
 '类型不是为难新手，而是防止把“电话号码”拿去相加、把“价格”当一句话处理。外部输入常先是文字，需要检查后转换。',
 ['把姓名、年龄、是否完成分别归类。','预测文字 "2" 和 "3" 拼接的结果。','解释电话号码为什么通常按文字保存。'],
 q('“是否已经付款”最适合哪种数据？',['数字','文字','真假'],2,'它只有是或否两种主要状态。'),
 {vocab:[['数据','程序要保存和处理的信息'],['类型','数据所属的类别'],['字符串','编程中对一段文字的常用名称']],mini:{type:'match',prompt:'把项目依次匹配到类型',pairs:[['年龄 18','数字'],['姓名 小林','文字'],['是否完成','真假']]}});

beginnerGuide('thinking-zero','think-04','变量：给数据贴一个名字',20,
 '变量不是神秘盒子。它只是给一份数据起名字，后面可以用名字找到它。',
 '例如把 8 叫作 price。名字应该说明内容。数据变化时，程序可以更新变量保存的值。变量名和变量里的值不是同一件事。',
 '名字：price\n里面的值：8\n读取 price → 得到 8',
 '可以把变量想成贴标签的抽屉。标签写“袜子”，抽屉里才是具体袜子。交换两个抽屉的标签和交换里面内容不是一回事。',
 ['给“用户姓名”“购物车数量”起清楚的英文或拼音变量名。','在小游戏里查看变量改变前后的值。','说出变量名 count 和值 3 的区别。'],
 q('变量最主要的作用是什么？',['给数据起名字，方便保存和使用','让电脑变快一万倍','代替所有文件'],0,'变量是程序运行时给数据起的名字。'),
 {vocab:[['变量','带名字的一份数据'],['变量名','用来找到数据的名称'],['值','变量当前保存的具体内容']],mini:{type:'choice',prompt:'score = 10 中，哪一个是值？',options:['score','=','10'],answer:2}});

beginnerGuide('thinking-zero','think-05','比较会得到“是”或“否”',18,
 '程序做决定前，经常先比较两个值。比较的结果只有真或假。',
 '大于、小于、等于都是比较。注意“把值放进变量”和“比较是否相等”是不同动作，许多语言使用不同符号。',
 '年龄 20 >= 18 → 真\n余额 5 >= 10 → 假',
 '边界最容易错。“18 岁及以上”包含 18，所以要使用“大于等于”，只写“大于”会漏掉刚好 18。',
 ['判断 5 > 3、5 < 3 和 5 = 5 的真假。','为“满 100 包邮”检查 99、100、101 三个边界。','在小游戏中连续判断三道比较。'],
 q('规则是“分数达到 60 就通过”，60 应该怎样？',['通过','不通过','无法判断'],0,'“达到 60”包含刚好 60。'),
 {vocab:[['比较','判断两个值之间的关系'],['真/假','比较或条件产生的两种结果'],['边界','规则开始或结束的临界值']],mini:{type:'choice',prompt:'10 >= 10 的结果是？',options:['真','假','10'],answer:0}});

beginnerGuide('thinking-zero','think-06','条件：如果……就……',20,
 '程序通过条件选择不同路线。它不是“思考”，而是在执行你写下的规则。',
 '条件先得到真或假。为真时走第一条路；否则走另一条路。多个条件要考虑先后和是否会重叠。',
 '如果 下雨：带伞\n否则：不带伞',
 '只写成功路线会漏掉失败情况。好的程序还会考虑输入为空、网络失败、权限不足等路线。',
 ['给“密码正确/错误”写出两条路线。','给“温度低于 18、18 到 26、高于 26”写三条路线。','玩一次岔路选择游戏。'],
 q('条件为假时，else 路线什么时候执行？',['条件不成立时','永远不执行','两个路线同时执行'],0,'else 处理前面条件不成立的情况。'),
 {vocab:[['条件','用于决定走哪条路线的真假判断'],['分支','程序可能选择的一条路线'],['否则','条件不成立时执行的路线']],mini:{type:'choice',prompt:'余额 5，商品 8，应该走哪条路？',options:['付款成功','余额不足'],answer:1}});

beginnerGuide('thinking-zero','think-07','重复：别把同一句写很多遍',20,
 '当同一动作要做很多次，可以使用重复。重复必须知道处理谁、何时停止。',
 '固定次数重复适合“做 3 次”；逐项重复适合“处理名单中的每个人”；条件重复适合“只要还有任务就继续”。',
 '名单：[小林, 小王, 小陈]\n对名单中的每个人：发送提醒',
 '没有停止条件的重复可能永远运行。写重复前先用一句中文说清楚“从哪里开始、每次做什么、什么时候结束”。',
 ['用一句话描述“把 3 个苹果逐个装箱”。','指出处理空名单时应该执行几次。','在小游戏中选择正确的重复方式。'],
 q('名单是空的，“对名单每个人打印姓名”会执行几次？',['0 次','1 次','无限次'],0,'没有元素就不会进入逐项重复。'),
 {vocab:[['循环/重复','让一组指令多次执行'],['一次迭代','重复过程中的其中一次'],['停止条件','决定什么时候结束']],mini:{type:'choice',prompt:'“给名单里每个人发消息”最适合？',options:['逐项重复','只执行一次','永不停止'],answer:0}});

beginnerGuide('thinking-zero','think-08','函数：把一组步骤包装起来',22,
 '经常使用的一组步骤可以起一个名字。以后只要叫这个名字，就能再次执行。',
 '函数有名字，可以接收输入，也可以交回结果。定义函数像写食谱；调用函数才像真正按食谱做菜。',
 '函数名：计算总价\n输入：单价、数量\n处理：相乘\n结果：总价',
 '函数应该做一件说得清楚的事。“处理所有事情”不是好名字。函数里的输入叫参数，交回给调用处的结果常叫返回值。',
 ['把“问候某人”设计成函数：名字、输入、输出。','区分定义函数和调用函数。','完成函数机器小游戏。'],
 q('只定义函数但不调用，会发生什么？',['步骤被保存，但通常还没有执行','一定执行十次','电脑关机'],0,'定义告诉电脑步骤；调用才要求执行。'),
 {vocab:[['函数','有名字、可重复使用的一组步骤'],['参数','调用时交给函数的输入'],['返回值','函数交回的结果']],mini:{type:'machine',prompt:'函数“加倍”收到 4，会输出什么？',input:'4',answer:'8'}});

beginnerGuide('thinking-zero','think-09','列表和字典：一组数据与带名字的数据',22,
 '程序常常需要保存一组项目，或者描述一个事物的多个属性。',
 '列表按位置保存一组项目；字典按名称保存信息。购物清单适合列表，一个用户的姓名和年龄适合字典。很多语言的位置从 0 开始计数。',
 '列表：["苹果", "牛奶"]\n字典：{"姓名": "小林", "年龄": 18}',
 '不要死背符号，先问数据是什么形状：是有顺序的一串，还是一个对象的多项属性？嵌套数据只是把这些形状组合起来。',
 ['给三门课程名称选择合适结构。','给一个商品的名称、价格、库存选择合适结构。','预测列表第一个元素的位置编号。'],
 q('保存一个人的姓名、年龄、城市，优先使用什么思路？',['带字段名字的字典','只有一个数字','永不结束的循环'],0,'每项信息有自己的字段名。'),
 {vocab:[['列表','按顺序保存的一组项目'],['字典/对象','按字段名保存多项信息'],['索引','列表项目的位置编号']],mini:{type:'choice',prompt:'“待办事项的一串标题”更像？',options:['列表','单个真假值','一个按钮'],answer:0}});

beginnerGuide('thinking-zero','think-10','Bug 与测试：先预测，再检查',25,
 'Bug 是程序行为和预期不一致。测试是用明确输入检查明确输出，不是随便点几下。',
 '一个有效测试至少包含输入、预期结果和实际结果。正常情况、边界情况、错误输入都值得检查。测试通过只说明这些用例通过。',
 '规则：两数相加\n输入：2 和 3\n预期：5\n实际：-1 → 发现 Bug',
 '调试时一次只改一个因素：先复现、缩小范围、观察数据、修改、重新测试。不要同时乱改十处。',
 ['给“判断成年”写 17、18、19 三个测试。','在小游戏里找到与预期不同的一步。','说出为什么只测一个正常输入不够。'],
 q('怎样证明测试真的能抓到某个 Bug？',['故意放入对应错误时测试会失败','测试名字很长','测试文件是绿色'],0,'反例能验证测试是否有辨别力。'),
 {vocab:[['Bug','实际行为不符合预期的问题'],['测试用例','输入和预期结果的具体组合'],['调试','寻找并修复问题的过程']],mini:{type:'choice',prompt:'规则“达到 60 通过”，哪个最关键的边界测试？',options:['60','1000','随便一个数'],answer:0}});

function slowPython(id,title,intro,concept,example,explain,steps,starter,solution,test,hint,reflection,extra={}){
 LESSONS.push({id,track:'python-slow',title,minutes:25,kind:'python',intro,concept,example,explain,steps,starter,solution,test,hint,reflection,vocab:extra.vocab||[],rescue:extra.rescue||[],mistakes:extra.mistakes||[],mini:extra.mini});
}
slowPython('pys-01','第一行代码由哪些小零件组成','代码不是一大团英文。先只认出名字、括号、引号和文字。','print 是电脑已经认识的功能名；英文圆括号包住要交给它的内容；英文引号包住一段文字。电脑从左到右辨认符号，再从上到下执行行。','print("你好")','print 像一个小喇叭；括号像把东西递给它；引号告诉电脑“里面只是文字，不是另一个名字”。符号必须成对。',['先不输入，逐个指出 print、左括号、左引号、文字、右引号、右括号。','复制示例运行，再只把“你好”改成自己的称呼。','故意删掉右引号，观察报错，再补回来。'],'# 在下一行输入：print("你好")\n','print("你好")','assert _output == "你好", "需要准确显示：你好"','先切到英文输入法，完整输入 print("你好")。','为什么文字两边要有引号？',{vocab:[['print','显示内容的 Python 功能'],['括号','装入交给功能的内容'],['引号','标记一段文字']],rescue:['先不要背，照着一个字符一个字符核对。','报 SyntaxError 时，先检查括号和引号是否成对。'],mini:{type:'order',prompt:'按代码出现顺序点击',items:['文字','print','括号'],answer:['print','括号','文字']}});
slowPython('pys-02','显示两行文字：理解执行顺序','电脑默认从第一行开始，一行完成后再执行下一行。','每个 print 是一条单独指令。换行表示下一条指令，不要把两条粘在同一对引号里。','# 第一行\nprint("早上好")\n# 第二行\nprint("开始学习")','# 开头是注释，给人阅读，Python 会跳过。两次 print 依次产生两行输出。',['运行示例并数输出有几行。','交换两条 print 的位置，观察输出顺序。','添加第三行“我会一步一步学”。'],'# 写两条 print\n','print("早上好")\nprint("开始学习")','assert _output.splitlines() == ["早上好","开始学习"]','每一行都写完整的 print("文字")。','代码行的顺序为什么重要？',{vocab:[['注释','写给人看的说明，# 后内容不执行'],['执行顺序','电脑运行代码的先后']],rescue:['输出挤在一起：确认使用了两条 print。']});
slowPython('pys-03','数字可以计算，文字只会拼接','不带引号的 2 是数字；带引号的 "2" 是文字。先预测，再运行。','数字可以加减乘除。文字相加表示首尾拼接。类型决定“加号”是什么意思。','print(2 + 3)      # 5\nprint("2" + "3")  # 23','注释后的 5 和 23 是预测。Python 先计算括号里的表达式，再把结果交给 print。',['分别运行数字相加和文字相加。','把 3 改成 10，先写下预测再运行。','尝试数字 2 加文字 "3"，读懂错误中的类型提示。'],'# 计算 8 加 4，并显示结果\n','print(8 + 4)','assert _output == "12", "应该显示数字计算结果 12"','数字不要加引号：print(8 + 4)。','为什么 "8" + "4" 不是 12？',{vocab:[['整数','没有小数部分的数字'],['表达式','会计算出一个值的代码']],rescue:['出现类型错误：检查一边是不是数字，另一边是不是带引号的文字。']});
slowPython('pys-04','变量：先保存，再使用','变量让我们不必在每处重复写同一个值。等号右边先计算，再把结果保存到左边名字。','price = 8 读作“把数字 8 保存到名字 price”，不是数学里的“永远相等”。下一行读取 price 时得到 8。','price = 8\ncount = 2\ntotal = price * count\nprint(total)','第一、二行保存输入；第三行读取它们并计算；第四行读取结果并显示。逐行追踪时，把每个变量当前值写在纸上。',['照示例运行。','把 price 改成 10，预测 total。','只改 count 为 3，再运行确认。'],'price = 6\ncount = 4\n# 计算并显示 total\n','price = 6\ncount = 4\ntotal = price * count\nprint(total)','assert total == 24, "total 应该保存 24"\nassert _output == "24", "还要显示 total"','补上 total = price * count 和 print(total)。','等号左右两边在这里分别扮演什么角色？',{vocab:[['赋值','把右边结果保存到左边变量名'],['读取变量','使用名字取得当前值']],rescue:['NameError：检查变量是否先赋值、拼写是否完全相同。'],mini:{type:'choice',prompt:'执行 x = 3 后，x 里是什么？',options:['3','字母 x','等号'],answer:0}});
slowPython('pys-05','文字变量和拼接','变量也能保存文字。用加号可以把几段文字拼成一段。','文字必须在引号里；变量名不加引号。"name" 是四个字母，name 是去读取名为 name 的变量。','name = "小林"\nmessage = "你好，" + name\nprint(message)','第一行保存姓名；第二行把固定问候和变量里的姓名拼接；第三行显示完整结果。',['运行并把姓名换成自己的称呼。','把 print(name) 和 print("name") 分别运行，比较结果。','加入感叹号，保证它也在引号里。'],'name = "小林"\n# 拼出：你好，小林！\n','name = "小林"\nmessage = "你好，" + name + "！"\nprint(message)','assert message == "你好，小林！"\nassert _output == message','固定文字用引号，name 变量不要加引号。','为什么 print("name") 不会显示小林？',{vocab:[['拼接','把多段文字首尾连接'],['固定文字','直接写在引号里的内容']],rescue:['少标点：检查逗号和感叹号是否放在引号里的正确位置。']});
slowPython('pys-06','输入：让使用者交给程序数据','input 会暂停程序，等待使用者输入文字。但网页自动练习不能弹出终端输入，所以先用函数参数模拟同一件事。','外部输入默认先按文字看待。需要计算时，先验证并转换成数字。学习阶段先分清“收到文字”和“转换数字”两个动作。','age_text = "18"\nage = int(age_text)\nprint(age + 1)','int 把符合格式的整数字符串转换成整数。"十八" 或空文字无法直接转换，会报错；真实程序要给出友好提示。',['运行示例。','把 "18" 改成 "20"，预测结果。','改成 "十八"，观察错误，再恢复数字文字。'],'count_text = "3"\n# 转成数字，计算再加 2\n','count_text = "3"\ncount = int(count_text)\nprint(count + 2)','assert count == 3\nassert _output == "5"','使用 count = int(count_text)。','为什么 input 得到的数字看起来像数字，却常需要转换？',{vocab:[['外部输入','来自用户、文件或网络的数据'],['转换','把一种数据类型变成另一种']],rescue:['ValueError：输入文字不能按当前规则转换为数字。']});
slowPython('pys-07','第一个判断：只有条件成立才执行','if 像一个岔路口。条件为真，缩进的代码执行；条件为假，缩进部分跳过。','冒号表示下面开始一个代码块；下一行前面的四个空格表示它属于 if。Python 用缩进表示代码层级。','age = 20\nif age >= 18:\n    print("可以注册")\nprint("检查结束")','年龄满足条件时会显示两行；不满足时只显示“检查结束”。最后一行没有缩进，所以不属于 if。',['运行 age=20。','改为 age=17，预测两行中哪行消失。','改为 age=18，检查边界是否包含。'],'age = 18\n# 满足 18 及以上时显示：可以注册\n','age = 18\nif age >= 18:\n    print("可以注册")','assert _output == "可以注册"','if 条件后写冒号，下一行缩进四个空格。','缩进为什么不是为了好看，而是代码含义？',{vocab:[['if','条件为真时执行一段代码'],['缩进','行首空格，用来表示代码属于哪个块'],['代码块','一起受某个结构控制的多行代码']],rescue:['IndentationError：检查行首空格。','SyntaxError 指向 if：检查冒号。']});
slowPython('pys-08','两条路线：if 和 else','只有“满足”还不够，else 用来处理条件不成立的情况。两条路线只会选择一条。','先检查 if 条件。为真走 if 块；否则走 else 块。else 不再写条件，但也需要冒号和缩进。','score = 55\nif score >= 60:\n    print("通过")\nelse:\n    print("继续练习")','55 不满足达到 60，所以执行 else。把分数改成 60 会走第一条路线。',['分别用 59、60、61 运行。','先预测每次结果并记录。','把 else 缩进故意改错，观察错误后恢复。'],'score = 59\n# 显示“通过”或“继续练习”\n','score = 59\nif score >= 60:\n    print("通过")\nelse:\n    print("继续练习")','assert _output == "继续练习"','完整写出 if 块和 else 块。','为什么测试 59、60、61 比只测试 80 更有用？',{vocab:[['else','前面条件不成立时执行的路线']],rescue:['两个结果都出现：检查第二个 print 是否真的缩进在 else 下面。']});
slowPython('pys-09','重复名单里的每一项','for 会从列表里依次取出每个项目，并执行缩进代码。变量会在每一轮保存当前项目。','列表用方括号包住；逗号分开项目。for name in names 可以读作“对 names 中的每个 name”。','names = ["小林", "小王", "小陈"]\nfor name in names:\n    print("你好，" + name)','第一轮 name 是小林，第二轮是小王，第三轮是小陈。列表为空时，一轮也不执行。',['运行并数有几行输出。','添加第四个姓名。','把列表改为空列表 []，预测输出。'],'names = ["苹果", "牛奶"]\n# 逐项显示：购买：项目名\n','names = ["苹果", "牛奶"]\nfor name in names:\n    print("购买：" + name)','assert _output.splitlines() == ["购买：苹果","购买：牛奶"]','for name in names: 后下一行缩进，并使用 name。','name 为什么会在每一轮变成不同内容？',{vocab:[['for','逐项重复'],['当前项','这一轮正在处理的数据']],rescue:['只显示一次：检查 print 是否缩进在 for 里面。']});
slowPython('pys-10','第一个函数：输入、处理、返回','现在把前面学过的计算包装成函数。先看定义，再看调用。','def 开始定义函数；括号里是参数；缩进部分是函数体；return 把结果交回调用位置。print 只是显示，return 才是交回结果。','def double(number):\n    result = number * 2\n    return result\n\nanswer = double(4)\nprint(answer)','运行到 def 时 Python 记住步骤。运行到 double(4) 才进入函数：number 收到 4，result 得到 8，return 交回 8，answer 接住它。',['用手指逐行追踪示例，写下 number、result、answer 的值。','把调用输入改成 5。','删掉 return，观察为何 answer 变成 None，再恢复。'],'# 完成函数：把传入数字加 1 并返回\ndef add_one(number):\n    pass\n','def add_one(number):\n    result = number + 1\n    return result','assert add_one(0) == 1\nassert add_one(9) == 10\nassert add_one(-1) == 0','把 pass 换成 result = number + 1 和 return result。','为什么只 print(result) 不能替代 return result？',{vocab:[['def','开始定义函数'],['pass','暂时什么都不做的占位指令'],['return','把函数结果交回调用处']],rescue:['函数返回 None：检查是否执行到了 return。','NameError：检查 result 是否在使用前赋值。'],mini:{type:'machine',prompt:'add_one 收到 9，应该返回？',input:'9',answer:'10'}});

